return $input.all().map(item => {
  // Read the student data from Google Sheets.
  const student = item.json;

  // Validate basic email address syntax.
  const email = String(student.Email ?? "").trim();
  const emailValid = /^[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)+$/.test(email);

  // Normalize and validate an Indian mobile number.
  const rawPhone = String(student.Phone ?? "").trim();
  const phone = rawPhone.replace(/[\s()-]/g, "");
  const phoneValid = /^(?:\+91|91)?[6-9]\d{9}$/.test(phone);

  // Return validated student data.
  return {
    json: {
      ...student,
      email_valid: emailValid,
      phone_valid: phoneValid,
      send_email: emailValid,
      recipient_email: emailValid ? email : "",
      phone_for_email: phoneValid ? rawPhone : "",
      phone_update_required: !phoneValid
    }
  };
});

return $input.all().map((item, index) => {
  // Read the AI-generated response.
  let data;

  try {
    const raw = String(item.json.text ?? "").trim();
    const cleaned = raw.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");
    data = JSON.parse(cleaned);
  } catch (error) {
    // Reject malformed AI output.
    data = {};
  }

  // Independently validate the recipient email format.
  const email = String(data.recipient_email ?? "").trim();
  const emailValid = /^[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)+$/.test(email);

  // Require the AI to explicitly approve sending.
  const sendEmail = emailValid && data.send_email === true && data.status === true;

  // Clean the email body and remove placeholder enrollment dates.
  let body = String(data.body ?? "")
    .replace(/^.*(?:Enrolled Date|Enrollment Date):\s*#+.*(?:\r?\n|$)/gim, "")
    .trim();

  // Ensure invalid recipients are not sent emails.
  return {
    json: {
      status: sendEmail,
      send_email: sendEmail,
      email_valid: emailValid,
      phone_valid: data.phone_valid === true,
      recipient_email: sendEmail ? email : "",
      subject: sendEmail ? String(data.subject ?? "").trim() : "",
      body: sendEmail ? body : "",
      validation_message: sendEmail
        ? String(data.validation_message ?? "Ready to send")
        : "Email not approved for sending."
    }
  };
});
